import{_ as a,o as s,c as i,a2 as e}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"スケジュールタスク","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/schedule.md","filePath":"ja/guides/schedule.md","lastUpdated":1792323081000}'),n={name:"ja/guides/schedule.md"};function o(r,t,d,l,h,p){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="スケジュールタスク" tabindex="-1">スケジュールタスク <a class="header-anchor" href="#スケジュールタスク" aria-label="Permalink to &quot;スケジュールタスク&quot;">​</a></h1><p><strong>cron 式</strong>を使って、決まった時刻に Bot へ仕事を 1 つ任せます: レポートの送信、外部データのチェック、メンテナンス、あるいはエージェント＋ツールに任せられる仕事なら何でも。</p><h2 id="これは何か" tabindex="-1">これは何か <a class="header-anchor" href="#これは何か" aria-label="Permalink to &quot;これは何か&quot;">​</a></h2><p><strong>Schedule</strong> は特定の Bot に紐付きます。時刻が来ると自然言語の <strong>command</strong> を 1 つエージェントに渡し、エージェントがツールやスキルを使ってそれを実行します。結果は接続済みのチャネルに届けられます。</p><hr><h2 id="フィールド" tabindex="-1">フィールド <a class="header-anchor" href="#フィールド" aria-label="Permalink to &quot;フィールド&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>表示名。例: <code>朝のダイジェスト</code></td></tr><tr><td><strong>Description</strong></td><td>短い説明</td></tr><tr><td><strong>Pattern</strong></td><td>5 フィールドの cron。例: <code>0 9 * * *</code> は毎日 9:00</td></tr><tr><td><strong>Command</strong></td><td>時刻が来たときにエージェントへ送られる自然言語のタスク</td></tr><tr><td><strong>Enabled</strong></td><td>有効かどうか</td></tr><tr><td><strong>Max Calls</strong></td><td>総実行回数の上限。空 = 無制限</td></tr><tr><td><strong>Current Calls</strong></td><td>すでに実行された回数</td></tr></tbody></table><hr><h2 id="cron-5-フィールド" tabindex="-1">Cron（5 フィールド） <a class="header-anchor" href="#cron-5-フィールド" aria-label="Permalink to &quot;Cron（5 フィールド）&quot;">​</a></h2><p>Bot のタイムゾーン——つまり Bot の <strong>一般</strong> タブの <strong>Timezone</strong> フィールド——で評価されます。未設定のときはサーバーのトップレベル <code>timezone</code> 設定（デフォルト <strong>UTC</strong>）にフォールバックします。5 つのフィールドは、分、時、日、月、曜日です。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌ 分 0–59</span></span>
<span class="line"><span>│ ┌ 時 0–23</span></span>
<span class="line"><span>│ │ ┌ 日 1–31</span></span>
<span class="line"><span>│ │ │ ┌ 月 1–12</span></span>
<span class="line"><span>│ │ │ │ ┌ 曜日 0–6、日曜=0</span></span>
<span class="line"><span>* * * * *</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Pattern</th><th>意味</th></tr></thead><tbody><tr><td><code>0 9 * * *</code></td><td>毎日 9:00</td></tr><tr><td><code>*/30 * * * *</code></td><td>30 分ごと</td></tr><tr><td><code>0 0 * * 1</code></td><td>毎週月曜 0:00</td></tr><tr><td><code>0 8,20 * * *</code></td><td>毎日 8:00 と 20:00</td></tr><tr><td><code>0 0 1 * *</code></td><td>毎月 1 日 0:00</td></tr></tbody></table><hr><h2 id="一覧を見る" tabindex="-1">一覧を見る <a class="header-anchor" href="#一覧を見る" aria-label="Permalink to &quot;一覧を見る&quot;">​</a></h2><p>Bot の <strong>スケジュール</strong> タブ: 名前、pattern、有効かどうか、実行回数など。<strong>Refresh</strong> で再読み込みします。</p><hr><h2 id="作成する" tabindex="-1">作成する <a class="header-anchor" href="#作成する" aria-label="Permalink to &quot;作成する&quot;">​</a></h2><h3 id="bot-自身に作らせる" tabindex="-1">Bot 自身に作らせる <a class="header-anchor" href="#bot-自身に作らせる" aria-label="Permalink to &quot;Bot 自身に作らせる&quot;">​</a></h3><p>Bot は <code>schedule</code> ツールを持っています。普通の言葉で頼めます。たとえば毎営業日の 8:00 にリポジトリの動きをまとめるよう伝えれば、Bot が cron を組み立てて登録します。</p><h3 id="api-を呼ぶ" tabindex="-1">API を呼ぶ <a class="header-anchor" href="#api-を呼ぶ" aria-label="Permalink to &quot;API を呼ぶ&quot;">​</a></h3><p><code>POST /api/bots/{bot_id}/schedule</code>。例:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Daily Digest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Summarize repository activity every morning&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pattern&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0 8 * * *&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Summarize yesterday&#39;s repository activity and send the result to Telegram.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;max_calls&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>（フィールド名は現在の API に従ってください。）</p><hr><h2 id="実行時に起きること" tabindex="-1">実行時に起きること <a class="header-anchor" href="#実行時に起きること" aria-label="Permalink to &quot;実行時に起きること&quot;">​</a></h2><ol><li>cron の時刻が来る</li><li><code>current_calls</code> が +1 される</li><li><code>max_calls</code> が設定されていて上限に達した場合、タスクは自動的にオフになる</li><li>エージェントが <code>command</code> とスケジュールのコンテキストを受け取る</li><li>ツールを使ってメッセージ送信や Web 検索などを行う</li><li>結果は接続済みのチャネルに届けられる</li></ol>`,26)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
